function navigationResults = animateMultiRobotNavigation( ...
    environment,startPoint,goalPoint,comparisonResults,cfg)
%ANIMATEMULTIROBOTNAVIGATION Simultaneous five-robot navigation.
%
% Each planning algorithm receives an independent differential-drive
% robot. Every robot uses:
% - the same environment,
% - the same initial pose,
% - the same clicked goal,
% - the same 360-degree LiDAR model,
% - the same DWA obstacle-avoidance controller,
% - the same kinematic and safety limits.
%
% The only intentional difference is the global path generated by A*,
% Dijkstra, RRT, RRT*, or PRM.

if ~cfg.compare.navigation.enabled
    navigationResults = struct([]);
    return;
end

plannerCount = numel(comparisonResults);
plannerNames = {comparisonResults.name};
panelOrder = [2 1 3 4 5]; % Dijkstra, A*, RRT, RRT*, PRM

maximumSteps = ceil( ...
    cfg.compare.navigation.maximumTime/ ...
    cfg.simulation.timeStep);

lidarAngles = linspace( ...
    -pi,pi,cfg.lidar.numberOfRays);

robotColours = [ ...
    0.95 0.20 0.18; ... % A*
    0.10 0.55 0.95; ... % Dijkstra
    0.95 0.62 0.08; ... % RRT
    0.65 0.25 0.90; ... % RRT*
    0.10 0.72 0.42];    % PRM

stateTemplate = struct( ...
    'name','', ...
    'path',zeros(0,2), ...
    'pose',[0;0;0], ...
    'command',[0;0], ...
    'progress',0, ...
    'reached',false, ...
    'failed',false, ...
    'completionTime',NaN, ...
    'history',zeros(maximumSteps+1,2), ...
    'historyCount',1, ...
    'travelledDistance',0, ...
    'minimumClearance',inf, ...
    'trackingErrorSquaredSum',0, ...
    'trackingSampleCount',0, ...
    'collisionEvents',0, ...
    'stallCounter',0, ...
    'lastTarget',startPoint, ...
    'lastPathInfo',struct(), ...
    'lastScan',struct(), ...
    'lastDebug',struct(), ...
    'slamState',struct(), ...
    'recoveryState',struct());

states = repmat(stateTemplate,plannerCount,1);

for plannerIndex = 1:plannerCount
    states(plannerIndex).name = comparisonResults(plannerIndex).name;
    states(plannerIndex).path = comparisonResults(plannerIndex).displayPath;
    states(plannerIndex).pose = [startPoint cfg.robot.startPose(3)]';
    states(plannerIndex).command = [0;0];
    states(plannerIndex).history(1,:) = startPoint;
    states(plannerIndex).failed = ...
        ~comparisonResults(plannerIndex).success || ...
        isempty(comparisonResults(plannerIndex).displayPath);

    states(plannerIndex).recoveryState.active = false;
    states(plannerIndex).recoveryState.preferredTurnDirection = 1;
    states(plannerIndex).recoveryState.activationTime = -inf;

    states(plannerIndex).lastScan = simulateLidar( ...
        states(plannerIndex).pose,environment,lidarAngles,cfg);

    if ~states(plannerIndex).failed
        [states(plannerIndex).lastTarget, ...
            states(plannerIndex).progress, ...
            states(plannerIndex).lastPathInfo] = pathFollower( ...
            states(plannerIndex).pose, ...
            states(plannerIndex).path,0,cfg,0);
    else
        states(plannerIndex).lastPathInfo = ...
            emptyPathInfoLocal(startPoint,goalPoint);
    end

    states(plannerIndex).lastDebug = ...
        defaultDebugLocal(states(plannerIndex).lastScan);

    states(plannerIndex).slamState = initializeSlamMap(cfg);
    states(plannerIndex).slamState = updateSlamMap( ...
        states(plannerIndex).slamState, ...
        states(plannerIndex).lastScan, ...
        cfg,states(plannerIndex).pose);
end

%% Figure and five synchronized panels
navigationFigure = figure( ...
    'Color',[0.015 0.020 0.045], ...
    'Position',[20 20 1900 1100], ...
    'Name','Simultaneous Multi-Algorithm Robot Navigation', ...
    'NumberTitle','off');

headerAxes = axes( ...
    'Parent',navigationFigure, ...
    'Position',[0.020 0.928 0.960 0.060], ...
    'Color',[0.015 0.020 0.045], ...
    'XLim',[0 1],'YLim',[0 1], ...
    'XTick',[],'YTick',[], ...
    'Visible','off');

headerText = text(headerAxes,0.5,0.66, ...
    'Five Autonomous Robots — A*, Dijkstra, RRT, RRT*, and PRM', ...
    'HorizontalAlignment','center', ...
    'VerticalAlignment','middle', ...
    'Color','w', ...
    'FontWeight','bold', ...
    'FontSize',17, ...
    'Interpreter','none');

subHeaderText = text(headerAxes,0.5,0.18, ...
    'Same start | Same clicked goal | Same world | Same LiDAR + DWA controller | Enlarged live SLAM maps', ...
    'HorizontalAlignment','center', ...
    'VerticalAlignment','middle', ...
    'Color',[0.70 0.85 1.00], ...
    'FontSize',10, ...
    'Interpreter','none'); %#ok<NASGU>

navPanelPositions = [ ...
    0.030 0.655 0.255 0.225; ... % Dijkstra navigation
    0.530 0.655 0.255 0.225; ... % A* navigation
    0.030 0.375 0.255 0.225; ... % RRT navigation
    0.530 0.375 0.255 0.225; ... % RRT* navigation
    0.155 0.095 0.255 0.225];    % PRM navigation

slamPanelPositions = [ ...
    0.295 0.655 0.205 0.225; ... % Dijkstra SLAM
    0.795 0.655 0.205 0.225; ... % A* SLAM
    0.295 0.375 0.205 0.225; ... % RRT SLAM
    0.795 0.375 0.205 0.225; ... % RRT* SLAM
    0.540 0.095 0.205 0.225];    % PRM SLAM    % PRM SLAM

panelTemplate = struct( ...
    'axes',[], ...
    'plannedPath',[], ...
    'actualPath',[], ...
    'lidarRays',[], ...
    'lidarHits',[], ...
    'lookAhead',[], ...
    'robot',struct(), ...
    'slamAxes',[], ...
    'slamImage',[], ...
    'slamTrajectory',[], ...
    'slamRobot',[], ...
    'slamGoal',[], ...
    'slamStart',[], ...
    'slamLabel',[], ...
    'statusText',[], ...
    'resultIndex',0);

panelHandles = repmat(panelTemplate,plannerCount,1);

for panelIndex = 1:plannerCount
    resultIndex = panelOrder(panelIndex);
    panelHandles(panelIndex).resultIndex = resultIndex;

    axesHandle = axes( ...
        'Parent',navigationFigure, ...
        'Position',navPanelPositions(panelIndex,:), ...
        'Color',[0.025 0.030 0.065]);

    panelHandles(panelIndex).axes = axesHandle;

    drawComparisonEnvironmentLocal( ...
        axesHandle,environment,startPoint,goalPoint);

    title(axesHandle,states(resultIndex).name, ...
        'Color','w','FontWeight','bold', ...
        'FontSize',11,'Interpreter','none');

    if ~states(resultIndex).failed
        panelHandles(panelIndex).plannedPath = plot( ...
            axesHandle, ...
            states(resultIndex).path(:,1), ...
            states(resultIndex).path(:,2), ...
            '--','Color',[0.15 0.50 1.00], ...
            'LineWidth',1.6);
    else
        panelHandles(panelIndex).plannedPath = plot( ...
            axesHandle,nan,nan,'--');
    end

    panelHandles(panelIndex).actualPath = plot( ...
        axesHandle,startPoint(1),startPoint(2), ...
        '-','Color',[1.00 0.24 0.18], ...
        'LineWidth',1.45);

    panelHandles(panelIndex).lidarRays = plot( ...
        axesHandle,nan,nan, ...
        'Color',[0.10 0.85 0.55], ...
        'LineWidth',0.28);

    panelHandles(panelIndex).lidarHits = plot( ...
        axesHandle,nan,nan,'.', ...
        'Color',[1.00 0.20 0.18], ...
        'MarkerSize',3);

    panelHandles(panelIndex).lookAhead = plot( ...
        axesHandle,nan,nan,'mo', ...
        'MarkerFaceColor','m','MarkerSize',4);

    robotConfig = cfg;
    robotConfig.visualization.robotBodyColor = ...
        robotColours(resultIndex,:);

    panelHandles(panelIndex).robot = drawRobot( ...
        axesHandle,states(resultIndex).pose, ...
        robotConfig,[]);

    panelHandles(panelIndex).statusText = text( ...
        axesHandle,0.02,0.98,'Preparing robot...', ...
        'Units','normalized', ...
        'HorizontalAlignment','left', ...
        'VerticalAlignment','top', ...
        'Color',[0.96 0.98 1.00], ...
        'BackgroundColor',[0.02 0.03 0.07], ...
        'Margin',3, ...
        'FontSize',7.3, ...
        'FontWeight','bold', ...
        'Interpreter','none');

    [panelHandles(panelIndex).slamAxes, ...
        panelHandles(panelIndex).slamImage, ...
        panelHandles(panelIndex).slamTrajectory, ...
        panelHandles(panelIndex).slamRobot, ...
        panelHandles(panelIndex).slamGoal, ...
        panelHandles(panelIndex).slamStart, ...
        panelHandles(panelIndex).slamLabel] = ...
        createSlamInsetLocal( ...
        navigationFigure,slamPanelPositions(panelIndex,:), ...
        states(resultIndex).slamState, ...
        states(resultIndex).pose, ...
        startPoint,goalPoint, ...
        states(resultIndex).name,cfg);
end

% Prevent axes toolbar icons from appearing in animation frames.
hideAxesToolbars(navigationFigure);

%% Video writer
videoObject = [];
temporaryImage = '';
targetVideoSize = [];

if cfg.compare.navigation.recordVideo
    videoObject = VideoWriter( ...
        fullfile(cfg.output.resultsFolder, ...
        'multi_algorithm_robot_navigation.avi'), ...
        'Motion JPEG AVI');

    videoObject.FrameRate = ...
        cfg.compare.navigation.frameRate;

    open(videoObject);
    temporaryImage = [tempname '.png'];
end

%% Simultaneous navigation loop
try
    for step = 1:maximumSteps
        simulationTime = ...
            (step-1)*cfg.simulation.timeStep;

        for plannerIndex = 1:plannerCount
            if states(plannerIndex).failed || ...
                    states(plannerIndex).reached
                continue;
            end

            previousPose = states(plannerIndex).pose;
            distanceToGoal = norm( ...
                previousPose(1:2)'-goalPoint);

            scan = simulateLidar( ...
                previousPose,environment,lidarAngles,cfg);

            [localTarget,newProgress,pathInfo] = ...
                pathFollower( ...
                previousPose,states(plannerIndex).path, ...
                states(plannerIndex).progress,cfg, ...
                states(plannerIndex).command(1));

            states(plannerIndex).progress = newProgress;

            [terminalCommand,terminalTrajectory, ...
                terminalDebug,terminalActive] = ...
                terminalGoalController( ...
                previousPose,states(plannerIndex).command, ...
                goalPoint,scan,cfg);

            if terminalActive && ...
                    pathInfo.remainingDistance < ...
                    1.5*cfg.goal.terminalModeRadius
                selectedCommand = terminalCommand;
                predictedTrajectory = terminalTrajectory; %#ok<NASGU>
                dwaDebug = terminalDebug;
            else
                cycleConfig = cfg;

                cycleConfig.robot.maximumLinearVelocity = min( ...
                    cfg.robot.maximumLinearVelocity, ...
                    pathInfo.speedLimit);

                cycleConfig.dwa.linearVelocitySamples = ...
                    cfg.compare.navigation.linearVelocitySamples;
                cycleConfig.dwa.angularVelocitySamples = ...
                    cfg.compare.navigation.angularVelocitySamples;
                cycleConfig.dwa.predictionTime = ...
                    cfg.compare.navigation.predictionTime;
                cycleConfig.dwa.predictionTimeStep = ...
                    cfg.compare.navigation.predictionTimeStep;

                cycleConfig.path.guidanceActive = true;
                cycleConfig.path.referencePoint = ...
                    pathInfo.projectedPoint;
                cycleConfig.path.referenceTangent = ...
                    pathInfo.pathTangent;
                cycleConfig.path.referencePath = ...
                    pathInfo.referencePath;
                cycleConfig.path.referenceProgressPoint = ...
                    localTarget;
                cycleConfig.path.currentCrossTrackError = ...
                    pathInfo.crossTrackError;

                [selectedCommand,predictedTrajectory,dwaDebug] = ...
                    dynamicWindowApproach( ...
                    previousPose,states(plannerIndex).command, ...
                    localTarget,scan, ...
                    states(plannerIndex).recoveryState, ...
                    cycleConfig); %#ok<ASGLU>
            end

            % Never remain unexpectedly motionless away from the goal.
            if selectedCommand(1) < 0.04 && ...
                    abs(selectedCommand(2)) < 0.10 && ...
                    distanceToGoal > cfg.goal.slowingRadius

                targetHeading = atan2( ...
                    localTarget(2)-previousPose(2), ...
                    localTarget(1)-previousPose(1));

                headingError = utilities( ...
                    'wrapAngle',targetHeading-previousPose(3));

                turnDirection = sign(headingError);

                if turnDirection == 0
                    if dwaDebug.openingLeft >= ...
                            dwaDebug.openingRight
                        turnDirection = 1;
                    else
                        turnDirection = -1;
                    end
                end

                selectedCommand = [ ...
                    0;turnDirection*min( ...
                    0.85,cfg.robot.maximumAngularVelocity)];
            end

            proposedPose = robotKinematics( ...
                previousPose,selectedCommand, ...
                cfg.simulation.timeStep);

            if collisionCheck(proposedPose,environment,cfg)
                states(plannerIndex).collisionEvents = ...
                    states(plannerIndex).collisionEvents+1;

                selectedCommand(1) = 0;

                if dwaDebug.openingLeft >= dwaDebug.openingRight
                    turnDirection = 1;
                else
                    turnDirection = -1;
                end

                selectedCommand(2) = ...
                    turnDirection*cfg.safety.emergencyTurnRate;

                proposedPose = robotKinematics( ...
                    previousPose,selectedCommand, ...
                    cfg.simulation.timeStep);

                if collisionCheck(proposedPose,environment,cfg)
                    proposedPose = previousPose;
                    selectedCommand = [0;0];
                end
            end

            movementDistance = norm( ...
                proposedPose(1:2)-previousPose(1:2));

            states(plannerIndex).travelledDistance = ...
                states(plannerIndex).travelledDistance+ ...
                movementDistance;

            states(plannerIndex).pose = proposedPose;
            states(plannerIndex).command = selectedCommand;
            states(plannerIndex).lastTarget = localTarget;
            states(plannerIndex).lastPathInfo = pathInfo;

            states(plannerIndex).lastScan = simulateLidar( ...
                proposedPose,environment,lidarAngles,cfg);

            states(plannerIndex).slamState = updateSlamMap( ...
                states(plannerIndex).slamState, ...
                states(plannerIndex).lastScan, ...
                cfg,proposedPose);

            states(plannerIndex).lastDebug = dwaDebug;

            states(plannerIndex).minimumClearance = min( ...
                states(plannerIndex).minimumClearance, ...
                dwaDebug.minimumClearance);

            states(plannerIndex).trackingErrorSquaredSum = ...
                states(plannerIndex).trackingErrorSquaredSum+ ...
                pathInfo.crossTrackError^2;

            states(plannerIndex).trackingSampleCount = ...
                states(plannerIndex).trackingSampleCount+1;

            states(plannerIndex).historyCount = ...
                states(plannerIndex).historyCount+1;

            states(plannerIndex).history( ...
                states(plannerIndex).historyCount,:) = ...
                proposedPose(1:2)';

            if norm(proposedPose(1:2)'-goalPoint) <= ...
                    cfg.goal.tolerance
                states(plannerIndex).reached = true;
                states(plannerIndex).completionTime = simulationTime;
                states(plannerIndex).command = [0;0];
            end
        end

        %% Update all five panels in the same frame
        for panelIndex = 1:plannerCount
            plannerIndex = panelHandles(panelIndex).resultIndex;
            currentState = states(plannerIndex);

            historyData = currentState.history( ...
                1:currentState.historyCount,:);

            set(panelHandles(panelIndex).actualPath, ...
                'XData',historyData(:,1), ...
                'YData',historyData(:,2));

            robotConfig = cfg;
            robotConfig.visualization.robotBodyColor = ...
                robotColours(plannerIndex,:);

            panelHandles(panelIndex).robot = drawRobot( ...
                panelHandles(panelIndex).axes, ...
                currentState.pose,robotConfig, ...
                panelHandles(panelIndex).robot);

            if ~currentState.failed
                set(panelHandles(panelIndex).lookAhead, ...
                    'XData',currentState.lastTarget(1), ...
                    'YData',currentState.lastTarget(2));
            end

            [rayX,rayY,hitX,hitY] = ...
                lidarDisplayDataLocal( ...
                currentState.pose,currentState.lastScan, ...
                cfg.compare.navigation.lidarDisplayStride);

            set(panelHandles(panelIndex).lidarRays, ...
                'XData',rayX,'YData',rayY);
            set(panelHandles(panelIndex).lidarHits, ...
                'XData',hitX,'YData',hitY);

            statusString = statusStringLocal( ...
                currentState,goalPoint,simulationTime);

            set(panelHandles(panelIndex).statusText, ...
                'String',statusString);

            updateSlamInsetLocal( ...
                panelHandles(panelIndex), ...
                currentState,startPoint,goalPoint,cfg);

            if currentState.reached
                set(panelHandles(panelIndex).statusText, ...
                    'Color',[0.45 1.00 0.55]);
            elseif currentState.failed
                set(panelHandles(panelIndex).statusText, ...
                    'Color',[1.00 0.35 0.35]);
            end
        end

        completedCount = sum([states.reached]);
        set(headerText,'String',sprintf( ...
            ['Five Autonomous Robots — Simulation %.1f s | ' ...
             'Reached goal: %d/%d'], ...
            simulationTime,completedCount,plannerCount));

        drawnow;

        if cfg.compare.navigation.recordVideo && ...
                mod(step,cfg.compare.navigation.videoCaptureStride) == 0

            hideAxesToolbars(navigationFigure);

            rgbFrame = utilities( ...
                'captureFigureRGB', ...
                navigationFigure,temporaryImage);

            if isempty(targetVideoSize)
                frameHeight = size(rgbFrame,1)- ...
                    mod(size(rgbFrame,1),2);
                frameWidth = size(rgbFrame,2)- ...
                    mod(size(rgbFrame,2),2);
                targetVideoSize = [frameHeight frameWidth];
            end

            rgbFrame = utilities( ...
                'fitFrame',rgbFrame,targetVideoSize);

            writeVideo(videoObject,rgbFrame);
        end

        if all([states.reached] | [states.failed])
            break;
        end
    end

    if cfg.compare.navigation.recordVideo
        finalHoldFrames = max(1,round( ...
            cfg.compare.navigation.finalHoldSeconds* ...
            cfg.compare.navigation.frameRate));

        for holdIndex = 1:finalHoldFrames
            hideAxesToolbars(navigationFigure);

            rgbFrame = utilities( ...
                'captureFigureRGB', ...
                navigationFigure,temporaryImage);

            if isempty(targetVideoSize)
                targetVideoSize = [ ...
                    size(rgbFrame,1)-mod(size(rgbFrame,1),2), ...
                    size(rgbFrame,2)-mod(size(rgbFrame,2),2)];
            end

            rgbFrame = utilities( ...
                'fitFrame',rgbFrame,targetVideoSize);

            writeVideo(videoObject,rgbFrame);
        end

        close(videoObject);
    end
catch errorInformation
    if cfg.compare.navigation.recordVideo
        try
            close(videoObject);
        catch
        end
    end

    if ~isempty(temporaryImage) && exist(temporaryImage,'file')
        delete(temporaryImage);
    end

    rethrow(errorInformation);
end

if ~isempty(temporaryImage) && exist(temporaryImage,'file')
    delete(temporaryImage);
end

hideAxesToolbars(navigationFigure);

print(navigationFigure,fullfile( ...
    cfg.output.resultsFolder, ...
    'multi_algorithm_robot_navigation_final.png'), ...
    '-dpng','-r180');

%% Metrics
Algorithm = plannerNames';
PlannerPathFound = ~[states.failed]';
ReachedGoal = [states.reached]';
CompletionTime_s = [states.completionTime]';
TravelledDistance_m = [states.travelledDistance]';
PlannedPathLength_m = [comparisonResults.pathLength]';
TrackingRMSE_m = zeros(plannerCount,1);
MinimumClearance_m = [states.minimumClearance]';
CollisionGuardEvents = [states.collisionEvents]';
SLAMExplored_percent = zeros(plannerCount,1);

for plannerIndex = 1:plannerCount
    if states(plannerIndex).trackingSampleCount > 0
        TrackingRMSE_m(plannerIndex) = sqrt( ...
            states(plannerIndex).trackingErrorSquaredSum/ ...
            states(plannerIndex).trackingSampleCount);
    else
        TrackingRMSE_m(plannerIndex) = NaN;
    end

    if isinf(MinimumClearance_m(plannerIndex))
        MinimumClearance_m(plannerIndex) = NaN;
    end

    SLAMExplored_percent(plannerIndex) = ...
        100*states(plannerIndex).slamState.exploredFraction;
end

navigationTable = table( ...
    Algorithm,PlannerPathFound,ReachedGoal, ...
    CompletionTime_s,TravelledDistance_m, ...
    PlannedPathLength_m,TrackingRMSE_m, ...
    MinimumClearance_m,CollisionGuardEvents, ...
    SLAMExplored_percent);

writetable(navigationTable,fullfile( ...
    cfg.output.resultsFolder, ...
    'multi_algorithm_robot_navigation_metrics.csv'));

% Create a second CSV using the requested result name.
writetable(navigationTable,fullfile( ...
    cfg.output.resultsFolder, ...
    'navigation_results.csv'));

% Trim unused preallocated trajectory rows before saving.
navigationResults = states;

for plannerIndex = 1:plannerCount
    navigationResults(plannerIndex).history = ...
        navigationResults(plannerIndex).history( ...
        1:navigationResults(plannerIndex).historyCount,:);
end

% Save all navigation states, paths, final SLAM maps, and metrics.
save(fullfile(cfg.output.resultsFolder, ...
    'navigation_results.mat'), ...
    'navigationResults','navigationTable', ...
    'comparisonResults','startPoint','goalPoint','cfg');

% Export one clean figure containing the final five SLAM maps.
exportFiveSlamMaps( ...
    navigationResults,startPoint,goalPoint,cfg);

disp(' ');
disp('===== MULTI-ALGORITHM ROBOT NAVIGATION METRICS =====');
disp(navigationTable);
end

function pathInfo = emptyPathInfoLocal(startPoint,goalPoint)

pathInfo.crossTrackError = NaN;
pathInfo.signedCrossTrackError = NaN;
pathInfo.remainingDistance = norm(goalPoint-startPoint);
pathInfo.progressFraction = 0;
pathInfo.speedLimit = 0;
pathInfo.targetIndex = 1;
pathInfo.nearestIndex = 1;
pathInfo.headingChange = 0;
pathInfo.projectedPoint = startPoint;
pathInfo.pathTangent = [1 0];
pathInfo.lookAheadDistance = 0;
pathInfo.progressArcLength = 0;
pathInfo.referencePath = startPoint;
pathInfo.correctionAngle = 0;
end

function debug = defaultDebugLocal(scan)

debug.bestScore = 0;
debug.validCandidateCount = 0;
debug.minimumClearance = min(scan.ranges);
debug.progressScore = 0;
debug.openingFront = mean(scan.ranges);
debug.openingLeft = mean(scan.ranges);
debug.openingRight = mean(scan.ranges);
debug.recoveryActive = false;
debug.terminalMode = false;
end

function drawComparisonEnvironmentLocal( ...
    axesHandle,environment,startPoint,goalPoint)

cla(axesHandle);
hold(axesHandle,'on');
axis(axesHandle,'equal');
axis(axesHandle,[ ...
    0 environment.worldWidth 0 environment.worldHeight]);
box(axesHandle,'on');
grid(axesHandle,'on');

set(axesHandle, ...
    'Color',[0.025 0.030 0.065], ...
    'XColor',[0.68 0.72 0.80], ...
    'YColor',[0.68 0.72 0.80], ...
    'GridColor',[0.22 0.25 0.35], ...
    'GridAlpha',0.20, ...
    'FontSize',7);

rectangle(axesHandle, ...
    'Position',[0 0 environment.worldWidth environment.worldHeight], ...
    'EdgeColor',[0.95 0.28 0.20], ...
    'LineWidth',2.0);

for index = 1:size(environment.rectangles,1)
    rectangle(axesHandle, ...
        'Position',environment.rectangles(index,:), ...
        'FaceColor',[0.38 0.09 0.09], ...
        'EdgeColor',[0.95 0.28 0.20], ...
        'LineWidth',0.9);
end

for index = 1:size(environment.circles,1)
    circle = environment.circles(index,:);
    rectangle(axesHandle, ...
        'Position',[ ...
        circle(1)-circle(3),circle(2)-circle(3), ...
        2*circle(3),2*circle(3)], ...
        'Curvature',[1 1], ...
        'FaceColor',[0.38 0.09 0.09], ...
        'EdgeColor',[0.95 0.28 0.20], ...
        'LineWidth',0.9);
end

for index = 1:numel(environment.polygons)
    polygon = environment.polygons{index};
    patch(axesHandle,polygon(:,1),polygon(:,2), ...
        [0.38 0.09 0.09], ...
        'EdgeColor',[0.95 0.28 0.20], ...
        'LineWidth',0.9);
end

plot(axesHandle,startPoint(1),startPoint(2), ...
    'o','Color',[1.00 1.00 0.00], ...
    'MarkerFaceColor',[0.85 1.00 0.00], ...
    'MarkerSize',5,'LineWidth',1.0);

plot(axesHandle,goalPoint(1),goalPoint(2), ...
    'p','Color',[1.00 0.20 0.95], ...
    'MarkerFaceColor',[1.00 0.20 0.95], ...
    'MarkerSize',8,'LineWidth',1.0);
end

function [rayX,rayY,hitX,hitY] = ...
    lidarDisplayDataLocal(pose,scan,displayStride)

indices = 1:displayStride:numel(scan.ranges);
rayX = nan(1,3*numel(indices));
rayY = nan(1,3*numel(indices));

for displayIndex = 1:numel(indices)
    rayIndex = indices(displayIndex);
    dataIndex = 3*(displayIndex-1)+1;

    rayX(dataIndex:dataIndex+2) = [ ...
        pose(1),scan.hitPoints(rayIndex,1),nan];

    rayY(dataIndex:dataIndex+2) = [ ...
        pose(2),scan.hitPoints(rayIndex,2),nan];
end

hitIndices = indices(scan.hitMask(indices));

if isempty(hitIndices)
    hitX = nan;
    hitY = nan;
else
    hitX = scan.hitPoints(hitIndices,1);
    hitY = scan.hitPoints(hitIndices,2);
end
end

function textValue = statusStringLocal( ...
    state,goalPoint,simulationTime)

if state.failed
    textValue = sprintf([ ...
        '%s\nNo valid planned path'],state.name);
    return;
end

if state.reached
    stateName = 'GOAL REACHED';
else
    stateName = 'NAVIGATING';
end

if isfield(state.lastPathInfo,'progressFraction')
    progressValue = 100*state.lastPathInfo.progressFraction;
    crossTrackError = state.lastPathInfo.crossTrackError;
else
    progressValue = 0;
    crossTrackError = NaN;
end

textValue = sprintf([ ...
    '%s | %s\n' ...
    't: %.1f s | goal: %.2f m\n' ...
    'v: %.2f m/s | w: %.2f rad/s\n' ...
    'path: %.1f%% | error: %.2f m\n' ...
    'SLAM explored: %.1f%%'], ...
    state.name,stateName,simulationTime, ...
    norm(state.pose(1:2)'-goalPoint), ...
    state.command(1),state.command(2), ...
    progressValue,crossTrackError, ...
    100*state.slamState.exploredFraction);
end

function [slamAxes,slamImage,slamTrajectory,slamRobot, ...
    slamGoal,slamStart,slamLabel] = createSlamInsetLocal( ...
    parentFigure,slamPosition,slamState,pose, ...
    startPoint,goalPoint,plannerName,cfg)
%CREATESLAMINSETLOCAL Create a live SLAM inset inside one panel.

slamAxes = axes( ...
    'Parent',parentFigure, ...
    'Position',slamPosition, ...
    'Color',[0.96 0.96 0.97], ...
    'XColor',[0.10 0.10 0.10], ...
    'YColor',[0.10 0.10 0.10], ...
    'LineWidth',1.1, ...
    'FontSize',8.5);

mapRgb = slamRgbLocal(slamState);

slamImage = image(slamAxes, ...
    [0 cfg.environment.worldWidth], ...
    [0 cfg.environment.worldHeight], ...
    mapRgb);

set(slamAxes,'YDir','normal');
axis(slamAxes,'equal');
axis(slamAxes,[0 cfg.environment.worldWidth 0 cfg.environment.worldHeight]);
hold(slamAxes,'on');
box(slamAxes,'on');
grid(slamAxes,'on');
xlabel(slamAxes,'X (m)','FontSize',8.5,'Color',[0.10 0.10 0.10]);
ylabel(slamAxes,'Y (m)','FontSize',8.5,'Color',[0.10 0.10 0.10]);
set(slamAxes,'GridAlpha',0.10,'MinorGridAlpha',0.05,'Layer','top');

slamTrajectory = plot(slamAxes, ...
    slamState.trajectory(:,1), ...
    slamState.trajectory(:,2), ...
    '-','Color',[0.88 0.10 0.10], ...
    'LineWidth',1.4);

slamStart = plot(slamAxes,startPoint(1),startPoint(2), ...
    'gs','MarkerFaceColor','g','MarkerSize',5,'LineWidth',1.0);

slamGoal = plot(slamAxes,goalPoint(1),goalPoint(2), ...
    'm*','MarkerSize',8,'LineWidth',1.2);

slamRobot = plot(slamAxes,pose(1),pose(2), ...
    'ko','MarkerFaceColor',[0.12 0.74 0.88],'MarkerSize',5.5,'LineWidth',1.0);

slamLabel = text(slamAxes,0.02,0.98, ...
    sprintf('SLAM explored\n0.0%%'), ...
    'Units','normalized', ...
    'HorizontalAlignment','left', ...
    'VerticalAlignment','top', ...
    'Color',[0.05 0.05 0.05], ...
    'FontSize',8.6, ...
    'FontWeight','bold', ...
    'BackgroundColor','w', ...
    'Margin',2, ...
    'Interpreter','none'); %#ok<NASGU>

title(slamAxes,sprintf('%s SLAM Live Occupancy Map',plannerName), ...
    'Color',[0.05 0.05 0.05],'FontSize',10.0,'FontWeight','bold', ...
    'Interpreter','none');
end

function updateSlamInsetLocal(panelHandle,state,startPoint,goalPoint,cfg)
%UPDATESLAMINSETLOCAL Refresh one planner's SLAM occupancy inset.

set(panelHandle.slamImage, ...
    'CData',slamRgbLocal(state.slamState), ...
    'XData',[0 cfg.environment.worldWidth], ...
    'YData',[0 cfg.environment.worldHeight]);

trajectory = state.slamState.trajectory(:,1:2);

set(panelHandle.slamTrajectory, ...
    'XData',trajectory(:,1), ...
    'YData',trajectory(:,2));

set(panelHandle.slamRobot, ...
    'XData',state.pose(1), ...
    'YData',state.pose(2));

set(panelHandle.slamGoal, ...
    'XData',goalPoint(1), ...
    'YData',goalPoint(2));

set(panelHandle.slamStart, ...
    'XData',startPoint(1), ...
    'YData',startPoint(2));

set(panelHandle.slamLabel, ...
    'String',sprintf('SLAM explored\n%.1f%%', ...
    100*state.slamState.exploredFraction));
end

function mapRgb = slamRgbLocal(slamState)
%SLAMRGBLOCAL Convert occupancy probabilities to a cleaner display map.

probability = slamState.probability;
observedMask = slamState.observed;

grayImage = 0.78*ones(size(probability));           % unknown = light gray

freeMask = observedMask & (probability <= 0.40);
occupiedMask = observedMask & (probability >= 0.60);
transitionMask = observedMask & ~(freeMask | occupiedMask);

grayImage(freeMask) = 0.98;                         % free = near white
grayImage(occupiedMask) = 0.03;                    % occupied = black

if any(transitionMask(:))
    transitionValues = 0.55 - 0.35*(probability(transitionMask) - 0.5);
    grayImage(transitionMask) = min(max(transitionValues,0.18),0.82);
end

mapRgb = repmat(grayImage,[1 1 3]);
end
